  const [count, setCount] = useState(0);
  console.log('ParentComponent renders');
  return (
    <div>
      <ChildComponent message="Hello" count={count} />
      <button onClick={() => setCount(count + 1)}>
        Increment count: {count}
      </button>
    </div>
  );
};

